// Só segue quando TODOS assinaram (document.finished).
// Sem token da API: o nome vem do aviso e o PDF assinado é baixado pelo link
// público da Autentique, montado a partir do ID (nunca usa URL vinda do aviso).
const b = $json.body || $json;
const ev = b.event || {};
if (ev.type !== 'document.finished') return [];
const d = ev.data || {};
const docId = String(d.id || '').replace(/[^A-Za-z0-9]/g, '');
if (!docId) return [];
const name = String(d.name || '');
if (!name) throw new Error('Aviso da Autentique sem nome do documento: ' + docId);
const signedUrl = 'https://api.autentique.com.br/documentos/' + docId + '/assinado.pdf';
return [{ json: { docId, name, signedUrl, eventId: ev.id || null } }];

const doc = { id: $json.docId, name: $json.name };
const signedUrl = $json.signedUrl;

// Nome do documento na Autentique = nome da pasta da reunião (sem .pdf/.docx)
const nome = String(doc.name || '').replace(/[.](pdf|docx?)$/i, '').split(' ').filter(Boolean).join(' ').trim();
const m = nome.match(/[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}h[0-9]{2}/);
const chave = m ? m[0] : '';
const BS = String.fromCharCode(92);
const esc = s => String(s).split(BS).join(BS + BS).split("'").join(BS + "'");
const SEM_PASTA = 'ATAs assinadas — sem pasta';

const conds = ["name contains '" + esc(nome) + "'", "name = '" + SEM_PASTA + "'"];
if (chave) conds.push("name contains '" + chave + "'");
const q = 'trashed = false and (' + conds.join(' or ') + ')';

return [{ json: { docId: doc.id, nome, chave, signedUrl, semPastaNome: SEM_PASTA, q } }];

const p = $('Preparar busca no Drive').first().json;
const files = $json.files || [];
const BASE = '<ID>'; // Meus Documentos
const FOLDER = 'application/vnd.google-apps.folder';
const norm = s => String(s).normalize('NFC').replace(/[–—]/g, '-').split(' ').filter(Boolean).join(' ').toLowerCase();

// 1º nome exato; senão, uma única pasta com a mesma data e hora de início
const pastas = files.filter(f => f.mimeType === FOLDER && f.name !== p.semPastaNome);
let pasta = pastas.find(f => norm(f.name) === norm(p.nome));
if (!pasta && p.chave) {
  const c = pastas.filter(f => f.name.startsWith(p.chave));
  if (c.length === 1) pasta = c[0];
}

const arquivo = (pasta ? pasta.name : p.nome) + ' — ATA ASSINADA.pdf';
// Aviso repetido da Autentique: já salvo, não duplica
if (files.some(f => f.mimeType !== FOLDER && f.name === arquivo)) return [];

const sem = files.find(f => f.mimeType === FOLDER && f.name === p.semPastaNome && (f.parents || []).includes(BASE));
return [{ json: {
  ...p,
  encontrou: !!pasta,
  pastaId: pasta ? pasta.id : null,
  pastaNome: pasta ? pasta.name : null,
  destinoId: pasta ? pasta.id : (sem ? sem.id : null),
  arquivo
} }];
